// Validate order data
const order = $input.first().json.body || $input.first().json;

if (!order.order_id || !order.customer || !order.items) {
  throw new Error('Missing required order fields');
}

if (!order.customer.email || !order.customer.name) {
  throw new Error('Missing customer info');
}

// Vietnamese phone validation
let phoneValid = true;
if (order.customer.phone) {
  const phoneRegex = /^(\+84|0)[0-9]{9,10}$/;
  phoneValid = phoneRegex.test(order.customer.phone.replace(/[\s-]/g, ''));
}

// Calculate total from items
const calculatedTotal = order.items.reduce((sum, item) => {
  return sum + ((item.qty || 1) * (item.price || 0));
}, 0);

const sanitized = {
  order_id: order.order_id,
  customer: {
    name: order.customer.name.trim(),
    email: order.customer.email.toLowerCase().trim(),
    phone: order.customer.phone?.trim() || '',
    address: order.customer.address || '',
    phone_valid: phoneValid
  },
  items: order.items,
  total: order.total || calculatedTotal,
  total_formatted: `${(order.total || calculatedTotal).toLocaleString('vi-VN')}đ`,
  payment_method: order.payment_method || 'COD',
  status: 'pending',
  created_at: new Date().toISOString(),
  timezone: 'Asia/Ho_Chi_Minh'
};

return [{ json: sanitized }];

